/**
 * Message catalogue for the standalone `.eml`/`.msg` window.
 *
 * Generated by `pnpm i18n:build` from the keys that window's module graph can
 * actually reach. It exists so opening a mail file from Finder does not load
 * the client's full catalogue.
 */
import { createLazyAppI18n } from './create';

const { instance, ready } = createLazyAppI18n({
  en: () => import('./viewer.en.json'),
  de: () => import('./viewer.de.json'),
});
export const viewerI18n = instance;
export const viewerI18nReady = ready;
